<?php require_once 'bootstrap.php';$sic=$_GET['sic']??'';$st=db()->prepare('SELECT * FROM dependex_world_registry WHERE sic_id=?');$st->execute([$sic]);$c=$st->fetch();if(!$c){http_response_code(404);exit('Club/ente non trovato');}$children=db()->prepare('SELECT sic_id,entity_name,network_level,status FROM dependex_world_registry WHERE parent_sic_id=? ORDER BY network_rank DESC,entity_name LIMIT 100');$children->execute([$sic]);$kids=$children->fetchAll();$drxSt=db()->prepare("SELECT COALESCE(SUM(CASE WHEN rank_eligible=1 AND status='POSTED' THEN amount ELSE 0 END),0) FROM drx_ledger WHERE club_sic_id=?");$drxSt->execute([$sic]);$qdrx=(float)$drxSt->fetchColumn();$snap=$c['network_level']==='LOCAL_CLUB'?club_rank_snapshot($sic):null;$clubRank=$snap['rank']??rank_for_drx($qdrx);$pageTitle=$c['entity_name'];require '_header.php';?>
<section class="section-head"><div><span class="eyebrow"><?=h($c['network_level'])?> · <?=h($c['country'])?></span><h1><?=h($c['entity_name'])?></h1><p><?=h($c['sic_id'])?></p></div><div class="drx-chip">◆ <?=number_format($qdrx,0,',','.')?> DRX · <?=h($clubRank)?></div></section>
<section class="metric-grid"><div class="metric"><b><?=h($clubRank)?></b><span>Rank DRX Club</span></div><div class="metric"><b><?=h((string)$c['direct_children'])?></b><span>Figli diretti</span></div><div class="metric"><b><?=h((string)$c['network_descendants'])?></b><span>Discendenti</span></div><div class="metric"><b><?=h((string)$c['public_data_score'])?>%</b><span>Completezza dati</span></div></section>
<section class="card"><h2>Scheda</h2><p><b>Status:</b> <?=h($c['status'])?><br><b>Luogo:</b> <?=h(implode(' · ',array_filter([$c['city'],$c['province'],$c['region'],$c['country']])))?><br><b>Indirizzo:</b> <?=h($c['address']?:'—')?><br><b>Incontri:</b> <?=h($c['meeting']?:'—')?><br><b>Telefono:</b> <?=h($c['phone']?:'—')?><br><b>Email:</b> <?=h($c['email']?:'—')?><br><b>Sito:</b> <?=h($c['website']?:'—')?><br><b>Geo:</b> <?=h($c['geo_accuracy']?:'PENDING')?> · confidenza <?=h((string)$c['geo_confidence'])?></p><div class="hero-actions"><?php if($c['website']):?><a class="btn" target="_blank" rel="noopener" href="<?=h($c['website'])?>">Sito</a><?php endif;?><?php if($c['email']):?><a class="btn" href="mailto:<?=h($c['email'])?>">Email</a><?php endif;?><?php if(!$c['is_synthetic']&&$c['latitude']!==null&&$c['longitude']!==null):?><a class="btn" target="_blank" rel="noopener" href="https://www.openstreetmap.org/?mlat=<?=urlencode((string)$c['latitude'])?>&mlon=<?=urlencode((string)$c['longitude'])?>">Indicazioni</a><?php endif;?></div></section>
<?php if($kids):?><section class="card"><h2>Nodi figli</h2><?php foreach($kids as $k):?><p><a href="club-card.php?sic=<?=urlencode($k['sic_id'])?>"><b><?=h($k['entity_name'])?></b> · <?=h($k['network_level'])?> · <?=h($k['status'])?></a></p><?php endforeach;?></section><?php endif;?>
<?php if($c['network_level']==='LOCAL_CLUB'):?><section class="card"><h2>Gamification Club</h2><p>Famiglie: <b><?=h((string)($snap['families']??0))?></b> · Eventi 365g: <b><?=h((string)($snap['events_365']??0))?></b> · Score: <b><?=h((string)($snap['compliance_score']??0))?>%</b></p><a class="btn" href="club-rank.php?club=<?=urlencode($sic)?>">Apri Rank Club</a></section><?php endif;?><section class="card"><h2>Fonte pubblica</h2><p><?=h($c['source_type'])?></p><?php if($c['source_url']):?><a class="btn" target="_blank" rel="noopener" href="<?=h($c['source_url'])?>">Apri fonte</a><?php endif;?></section><?php require '_footer.php';?>